#include "ram_bridge.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static ta_model m;
static uint8_t runtime[76800],uid[14],full[14];
static unsigned checks,failures,groups,queries,rom_calls,reset_requests;
static uint32_t last_query_address,last_rom_ticks;
static int query_result=1;
#define CHECK(x) do{checks++;if(!(x)){failures++;printf("FAIL line=%d %s\n",__LINE__,#x);}}while(0)
static void put(uint32_t a,uint32_t v,unsigned n){unsigned i;for(i=0;i<n;i++){m.memory.ram[a-TF_RAM_BASE+i]=(uint8_t)(v>>(i*8));m.memory.known[a-TF_RAM_BASE+i]=255;}}
static uint32_t get(uint32_t a,unsigned n){unsigned i;uint32_t v=0;for(i=0;i<n;i++)v|=(uint32_t)m.memory.ram[a-TF_RAM_BASE+i]<<(i*8);return v;}
static int conn(void *p,uint16_t h,uint32_t a){(void)p;CHECK(h==7);queries++;last_query_address=a;return query_result;}
static int rom(void *p,unsigned off,uint8_t task,uint16_t e,uint32_t ticks){(void)p;(void)task;(void)e;rom_calls++;if(off==88)last_rom_ticks=ticks;return off==88?1:0;}
static void read_flash(void *p,uint32_t a,uint8_t *d,uint8_t *k,size_t n){(void)p;(void)a;memset(d,0,n);memset(k,255,n);if(n>4)d[4]=2;}
static void observe(void *p,const tc_event *e){(void)p;if(e->kind==TC_EV_RESET_REQUEST){reset_requests++;CHECK(get(TF_REGISTRY+28,4)==0);}}
static void fresh(tc_image image){tc_backend io;tf_backend f;ta_link_backend l;memset(&io,0,sizeof(io));memset(&f,0,sizeof(f));io.read=read_flash;io.event=observe;f.rom_status=rom;f.memory_contracts=1;l.context=NULL;l.connection_status=conn;ta_init(&m,image,runtime,sizeof(runtime),&io,&f,&l);tc_identity(&m.ota,uid,full);m.ota.alloc_ok=TC_YES;queries=rom_calls=reset_requests=0;query_result=1;
    if(image==TC_BOOT){put(0x20004080,0,1);put(0x20004084,0,4);put(0x2000408b,0,1);put(0x2000407e,7,2);put(0x2000407c,3,1);put(0x2000408d,4,1);}
    else{put(0x2000409e,7,2);put(0x200040a2,9,2);put(0x2000409c,3,1);put(0x200040a0,4,1);}}
static size_t frame(uint8_t *b,uint8_t cmd,const uint8_t *d,size_t n){size_t i;uint8_t sum=(uint8_t)(cmd+(n>>8)+(n&255));b[0]=0x55;b[1]=0x7f;b[2]=cmd;b[3]=(uint8_t)(n>>8);b[4]=(uint8_t)n;for(i=0;i<n;i++){b[5+i]=d[i];sum=(uint8_t)(sum+d[i]);}b[n+5]=sum;return n+6;}
static void group(const char *s){groups++;printf("GROUP %s\n",s);}
static void boot_alias(void){uint8_t wire[64],d[15];size_t n;unsigned i;group("BOOT reply alias, copy-before-builder and next zero-length command");fresh(TC_BOOT);d[0]=1;memcpy(d+1,uid,14);n=frame(wire,'S',d,15);CHECK(ta_receive(&m,7,wire,n,100)==n);CHECK(get(0x2000408b,1)==1);CHECK(get(0x200090aa,1)==0x55);CHECK(get(0x200090ae,1)==15);for(i=0;i<15;i++)CHECK(get(0x200090af+i,1)==d[i]);CHECK(get(0x200090a6,2)==21);CHECK(get(0x200090a8,2)==0);CHECK(m.replies_committed==1);CHECK(queries==1);CHECK(last_query_address==0x20004068);
    n=frame(wire,'S',NULL,0);CHECK(ta_receive(&m,7,wire,n,101)==n);CHECK(get(0x2000408b,1)==0);CHECK(get(0x200090aa,1)==0x55);CHECK(get(0x200090af,1)=='S');CHECK(get(0x200090a6,2)==6);CHECK(m.replies_committed==2);}
static void runtime_slots(void){uint8_t wire[64],d[15];size_t n;unsigned i;group("Runtime SRAM RX and selected TX remain distinct, no slot append");fresh(TC_RUNTIME);d[0]=0;memcpy(d+1,uid,14);n=frame(wire,'S',d,15);CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(get(0x200040b1,1)==1);for(i=0;i<15;i++)CHECK(get(0x2000b9d8+i,1)==d[i]);CHECK(get(0x2000b192,1)==0x55);CHECK(get(0x2000b18e,2)==21);CHECK(get(0x2000b190,2)==0);CHECK(last_query_address==0x20004088);put(0x2000b18e,333,2);put(0x2000b190,99,2);
    n=frame(wire,'S',NULL,0);CHECK(ta_receive(&m,7,wire,n,11)==n);CHECK(get(0x2000b9d8,1)==255);CHECK(get(0x2000b18e,2)==6);CHECK(get(0x2000b190,2)==0);CHECK(get(0x200040b1,1)==0);}
static void reply_gates(void){uint8_t wire[64],d[15];size_t n;group("alloc and connection failures preserve RAM, unknown branch invalidates only possible writes");fresh(TC_BOOT);d[0]=1;memcpy(d+1,uid,14);n=frame(wire,'S',d,15);m.ota.alloc_ok=TC_NO;CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(get(0x200090aa,1)==1);CHECK(m.replies_committed==0);CHECK(queries==0);fresh(TC_BOOT);query_result=0;CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(get(0x200090aa,1)==1);CHECK(m.replies_committed==0);CHECK(queries==1);fresh(TC_BOOT);query_result=-1;CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(m.memory.known[0x90aa]==0);CHECK(m.memory.known[0x90a6]==0);CHECK(m.replies_committed==0);CHECK(m.unresolved!=0);CHECK(get(0x2000408b,1)==1);}
static void interleaved_handle(void){uint8_t wire[16];size_t n;group("single parser attributes completion to last chunk handle and chooses second matching slot");fresh(TC_RUNTIME);n=frame(wire,'R',NULL,0);put(0x2000c792,7,2);put(0x2000c794,1,1);m.ota.general_auth=TC_NO;CHECK(ta_receive(&m,9,wire,3,10)==3);CHECK(get(0x200040a4,1)==3);CHECK(ta_receive(&m,7,wire+3,n-3,11)==n-3);CHECK(get(0x200040a4,1)==0);CHECK(m.ota.command_count==1);CHECK(m.handle==7);CHECK(m.ota.reply_frame_length==0);fresh(TC_RUNTIME);put(0x2000409e,9,2);put(0x200040a2,7,2);n=frame(wire,'S',NULL,0);CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(last_query_address==0x20004088);CHECK(get(0x2000b5b8,1)==0x55);CHECK(get(0x2000b5b4,2)==6);CHECK(get(0x2000b18e,2)==0);}
static void gap_and_unknown(void){uint8_t wire[16];size_t n;group("native unsigned clock gap, zero-length input, unknown parser boundary");fresh(TC_RUNTIME);put(0x200040b1,1,1);put(0x200040a4,5,1);put(0x200040a8,0xffffff00,4);CHECK(ta_receive(&m,7,NULL,0,0x2c)==0);CHECK(get(0x200040a4,1)==0);CHECK(get(0x200040b1,1)==1);CHECK(get(0x200040a8,4)==0x2c);put(0x200040a4,3,1);put(0x200040a8,100,4);CHECK(ta_receive(&m,7,NULL,0,399)==0);CHECK(get(0x200040a4,1)==3);CHECK(ta_receive(&m,7,NULL,0,699)==0);CHECK(get(0x200040a4,1)==0);fresh(TC_RUNTIME);m.memory.known[0x40a4]=0;n=frame(wire,'R',NULL,0);CHECK(ta_receive(&m,7,wire,n,10)==0);CHECK(m.halted==1);CHECK(m.ota.command_count==0);CHECK(get(0x200040a8,4)==10);}
static void schedule_shared(void){uint8_t wire[16];size_t n;group("OTA E and feature actions use same native callback registry, conversion once");fresh(TC_RUNTIME);put(0x200040b1,1,1);CHECK(tf_schedule(&m.memory,0xd62e,0,10,0)==0);n=frame(wire,'E',NULL,0);CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(get(0x200040b1,1)==0);CHECK(get(TF_REGISTRY+4,4)==0xd62e);CHECK(get(TF_REGISTRY+16,4)==0x8e12);CHECK(get(TF_REGISTRY+28,4)==0x99c6);CHECK(m.memory.last_ticks==640);CHECK(last_rom_ticks==640);CHECK(m.last_schedule_result==0);CHECK(tf_dispatch(&m.memory,1)==0);CHECK(get(0x2000bf6a,1)==20);CHECK(get(TF_REGISTRY+16,4)==0x8e12);CHECK(ta_dispatch_runtime(&m,4)==4);CHECK(reset_requests==0&&m.halted==1);CHECK(m.native_callbacks.flow==NC_HALT);CHECK(get(TF_REGISTRY+28,4)==0);CHECK(get(TF_REGISTRY+16,4)==0x8e12);}
static void unsupported_boundary(void){uint8_t wire[16];size_t n;group("general auth is native SRAM; deep missing helper halts after confirmed prefix");fresh(TC_RUNTIME);put(0x2000c792,7,2);put(0x2000c794,1,1);put(0x200040af,1,1);n=frame(wire,0xbb,NULL,0);CHECK(ta_receive(&m,7,wire,n,10)==n-1);CHECK(m.halted==1);CHECK(get(0x200040a4,1)==6);CHECK(m.ota.command_count==1);CHECK(m.unresolved!=0);fresh(TC_RUNTIME);n=frame(wire,'R',NULL,0);m.ota.general_auth=TC_YES;CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(m.halted==0);CHECK(m.ota.command_count==1);CHECK(m.ota.reply_command==0xa8);CHECK(m.ota.reply_data[0]==255);}
static void parser_edges(void){uint8_t wire[1050],d[1041];size_t n;group("checksum failure, native parser limit and empty chunk gap do not clear OTA");fresh(TC_RUNTIME);put(0x200040b1,1,1);n=frame(wire,'E',NULL,0);wire[n-1]^=1;CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(get(0x200040b1,1)==1);CHECK(m.ota.command_count==0);CHECK(get(0x200040a4,1)==0);memset(d,0x11,sizeof(d));n=frame(wire,'S',d,sizeof(d));CHECK(ta_receive(&m,7,wire,n,11)==n);CHECK(m.ota.command_count==0);CHECK(get(0x20004096,2)==1041);CHECK(get(0x20004092,2)==0);CHECK(get(0x200040b1,1)==1);fresh(TC_RUNTIME);m.memory.known[0x40a8]=0;n=frame(wire,'S',NULL,0);CHECK(ta_receive(&m,7,wire,n,10)==n);CHECK(m.halted==0);CHECK(get(0x200040a4,1)==0);}
static void native_order_review(void){uint8_t byte=3;group("source-derived invalid state/index and stores before unknown sum/length");fresh(TC_RUNTIME);put(0x200040a4,255,1);CHECK(ta_receive(&m,7,&byte,1,10)==1);CHECK(get(0x200040a4,1)==0);CHECK(m.halted==0);fresh(TC_RUNTIME);put(0x200040a4,5,1);put(0x20004092,1040,2);put(0x200040ad,17,1);CHECK(ta_receive(&m,7,&byte,1,10)==1);CHECK(get(0x200040a4,1)==0);CHECK(get(0x200040ad,1)==17);CHECK(m.halted==0);fresh(TC_RUNTIME);put(0x200040a4,4,1);put(0x20004092,123,2);m.memory.known[0x4096]=0;CHECK(ta_receive(&m,7,&byte,1,10)==0);CHECK(get(0x20004092,2)==0);CHECK(m.halted==1);fresh(TC_RUNTIME);put(0x200040a4,2,1);m.memory.known[0x40ad]=0;CHECK(ta_receive(&m,7,&byte,1,10)==1);CHECK(get(0x200040a4,1)==3);CHECK(get(0x200040ac,1)==3);CHECK(m.halted==1);fresh(TC_RUNTIME);put(0x200040a4,4,1);put(0x20004096,0,2);m.memory.known[0x40ad]=0;CHECK(ta_receive(&m,7,&byte,1,10)==1);CHECK(get(0x200040a4,1)==5);CHECK(get(0x20004096,2)==3);}
int main(int argc,char **argv){FILE *p;unsigned i;if(argc!=2)return 2;p=fopen(argv[1],"rb");if(!p||fread(runtime,1,sizeof(runtime),p)!=sizeof(runtime)){if(p)fclose(p);return 2;}fclose(p);for(i=0;i<14;i++){uid[i]=(uint8_t)(i+17);full[i]=255;}boot_alias();runtime_slots();reply_gates();interleaved_handle();gap_and_unknown();schedule_shared();unsupported_boundary();parser_edges();native_order_review();printf("RAM_BRIDGE_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
